function result=v3_fit_periodic(t,reference,response,frequency,onset)
t=t(:);reference=reference(:);response=response(:);D=[sin(2*pi*frequency*(t-onset)),cos(2*pi*frequency*(t-onset)),ones(size(t)),t-mean(t)];assert(numel(t)>10 && rank(D)==4 && all(isfinite([reference;response])));a=D\reference;b=D\response;Aref=norm(a(1:2));Aout=norm(b(1:2));assert(Aref>.01,'v3:fit','Near-zero reference fundamental');phase=atan2(a(2),a(1))-atan2(b(2),b(1));DH=[D,sin(4*pi*frequency*(t-onset)),cos(4*pi*frequency*(t-onset)),sin(6*pi*frequency*(t-onset)),cos(6*pi*frequency*(t-onset))];bh=DH\response;ratio=Aout/Aref;result=struct('A_ref_deg',Aref,'A_out_deg',Aout,'gain_ratio',ratio,'gain_db',20*log10(max(realmin,ratio)),'phase_lag_deg',rad2deg(atan2(sin(phase),cos(phase))),'phase_unreliable',ratio<.05,'pitch_rmse_deg',sqrt(mean((response-reference).^2)),'fit_residual_deg',sqrt(mean((response-D*b).^2)),'bias_deg',b(3)-a(3),'trend_deg_per_s',b(4)-a(4),'harmonic2_deg',norm(bh(5:6)),'harmonic3_deg',norm(bh(7:8)));
end
